  }

  /* 6. The down point survives a secondary slot's events (slot 0 stays ours). */
  {
    struct input_event raw[] = {
      F_SLOT0, F_TRACK(5), F_X(2000), F_Y(4050), F_SYN,
      ev(EV_ABS, ABS_MT_SLOT, 1), ev(EV_ABS, ABS_MT_TRACKING_ID, 9),
