### services/nuxel-session/systemd/nuxel-bootmode-oneshot.service
[Unit]
Description=Nuxel one-shot boot mode consumer (verbose/safe/diag/debug flags)
Documentation=file:/usr/share/doc/nuxel/
After=local-fs.target
Before=nuxel-wayland.service nuxel-ui.service
ConditionPathExists=/var/lib/nuxel/boot

[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=/usr/local/bin/nuxel-bootmode-oneshot.sh
StandardOutput=journal
StandardError=journal

[Install]
WantedBy=multi-user.target

### tools/s10plus/a33/nuxel-bootmode-oneshot.sh
#!/bin/bash
# nuxel-bootmode-oneshot.sh — consume one-shot boot-mode flags at userspace boot.
# Runs once, early (before the display/launcher), from nuxel-bootmode-oneshot.service.
# Each flag is consumed exactly once and cleared so the NEXT boot is always normal.
set -u
FLAGS=/var/lib/nuxel/boot
RUN=/run/nuxel
mkdir -p "$FLAGS" "$RUN" 2>/dev/null || true

if [ -f "$FLAGS/verbose-once" ]; then
  # Verbose boot for THIS boot only. The display/bridge reads /run/nuxel/verbose-boot.
  cat > "$RUN/verbose-boot" <<STATE
EFFECTIVE=1
SOURCE=bootmode-oneshot
CONFIG=verbose-once
STATE
  rm -f "$FLAGS/verbose-once"
fi

if [ -f "$FLAGS/safe-mode-once" ]; then
  # Safe mode for THIS boot only: disable the animation handoff/launcher extras.
  echo "1" > "$RUN/safe-mode"
  rm -f "$FLAGS/safe-mode-once"
fi

if [ -f "$FLAGS/diag-once" ]; then
  mkdir -p /diag
  if [ -x /usr/local/bin/nuxel-diag-pack.sh ]; then
    /usr/local/bin/nuxel-diag-pack.sh || true
  fi
  rm -f "$FLAGS/diag-once"
fi

if [ -f "$FLAGS/debug-once" ]; then
  # Debug logging for THIS boot only. A marker the services read; never persisted.
  echo "1" > "$RUN/debug-logging"
  rm -f "$FLAGS/debug-once"
fi
exit 0

### tools/s10plus/a33/nuxel-diag-pack.sh
#!/bin/bash
# nuxel-diag-pack.sh — collect a full diagnostics pack into
# /diag/<YYYY-MM-DD_HH-MM-SS_diagnostics-logs-stats.gz
# Read-only collection of logs, stats, hardware identity, versions and settings.
set -u
TS=$(date +%Y-%m-%d_%H-%M-%S)
OUTDIR=/diag
TMP=$(mktemp -d "${TMPDIR:-/tmp}/nuxel-diag.XXXXXX")
D="$TMP/$TS"
mkdir -p "$D"
{
  echo "# Nuxel diagnostics pack"
  echo "at=$TS"
  echo "hostname=$(cat /etc/hostname 2>/dev/null)"
  echo "uname=$(uname -a 2>/dev/null)"
  echo "uptime=$(cat /proc/uptime 2>/dev/null)"
  echo "cmdline=$(cat /proc/cmdline 2>/dev/null)"
  echo "fedora=$(cat /etc/fedora-release 2>/dev/null)"
  echo "nuxel_version=$(cat /VERSION 2>/dev/null)"
  echo "model=$(cat /proc/device-tree/model 2>/dev/null)"
  echo "board=$(cat /sys/firmware/devicetree/base/model 2>/dev/null)"
} > "$D/overview.txt" 2>/dev/null

# logs
mkdir -p "$D/logs"
cp -a /var/log/nuxel "$D/logs/nuxel" 2>/dev/null || true
cp -a /var/log/messages "$D/logs/messages" 2>/dev/null || true
cp -a /var/log/journal "$D/logs/journal" 2>/dev/null || true
journalctl -b --no-pager > "$D/logs/journalctl-boot.txt" 2>/dev/null || true
journalctl -b -p err --no-pager > "$D/logs/journalctl-err.txt" 2>/dev/null || true

# state
mkdir -p "$D/state"
for f in /run/nuxel/* /var/lib/nuxel/fb-owner /var/lib/nuxel/buttons /var/lib/nuxel/anim-handoff.log; do
  [ -e "$f" ] && cp -a "$f" "$D/state/" 2>/dev/null || true
done

# hardware + services
{
  echo "### systemctl failed"
  systemctl --failed --no-pager 2>&1
  echo "### systemctl running"
  systemctl list-units --type=service --state=running --no-pager 2>&1
  echo "### input devices"
  cat /proc/bus/input/devices 2>&1
  echo "### interrupts"
  grep -iE "sec_ts|tsp|touch|usb|dwc3|wlan|brcm|madera" /proc/interrupts 2>&1
  echo "### block"
  lsblk 2>&1 || cat /proc/partitions 2>&1
  echo "### cpu"
  cat /proc/cpuinfo 2>&1
  echo "### mem"
  cat /proc/meminfo 2>&1
  echo "### df"
  df -h 2>&1
  echo "### modules"
  lsmod 2>&1
  echo "### mounts"
  cat /proc/mounts 2>&1
} > "$D/hardware-services.txt" 2>/dev/null

# configs
mkdir -p "$D/etc-nuxel"
cp -a /etc/nuxel "$D/etc-nuxel/nuxel" 2>/dev/null || true

# versions + git hashes
{
  echo "rpm_packages=$(rpm -qa 2>/dev/null | wc -l)"
  rpm -qa 2>/dev/null | sort > "$D/rpmlist.txt" || true
  for b in /usr/lib/nuxel/nuxel-* /usr/local/bin/nuxel-*; do
    [ -e "$b" ] || continue
    echo "$(sha256sum "$b" 2>/dev/null) $b"
  done > "$D/binaries-sha256.txt" 2>/dev/null
} 

(cd "$TMP" && tar -czf "$OUTDIR/${TS}_diagnostics-logs-stats.gz" "$TS") 2>/dev/null
# fallback if tar missing
if [ ! -s "$OUTDIR/${TS}_diagnostics-logs-stats.gz" ]; then
  (cd "$TMP" && gzip -c -r "$TS" > "$OUTDIR/${TS}_diagnostics-logs-stats.gz") 2>/dev/null || true
fi
rm -rf "$TMP" 2>/dev/null || true
echo "DIAG_PACK=$OUTDIR/${TS}_diagnostics-logs-stats.gz"
exit 0

### tools/s10plus/a33/nuxel-mt.h
/*
 * nuxel-mt.h — the S10+ touchscreen (MT protocol B) frame parser.
 *
 * WHY THIS IS A SEPARATE, TESTABLE UNIT
 *   The sec_ts driver reports a new contact as
 *
 *       ABS_MT_SLOT 0
 *       ABS_MT_TRACKING_ID <id>
 *       ABS_MT_POSITION_X <x>        (often in the same frame)
 *       ABS_MT_POSITION_Y <y>
 *       SYN_REPORT
 *
 *   Emitting a "down" event at ABS_MT_TRACKING_ID therefore uses the PREVIOUS
 *   frame's coordinates.  On the first touch of a session those are 0,0, which
 *   made every tap look like a swipe from the top-left edge (the observed
 *   spurious `action=back`) and made a real swipe-up-from-the-bottom
 *   indistinguishable from a gesture that started at 0,0 (so `home` never
 *   fired).  The contact is only complete at SYN_REPORT, so this parser emits
 *   DOWN/MOVE/UP there, after ABS_MT_POSITION_X/Y have been applied.
 *
 *   The parser is dependency-free apart from <linux/input.h>, so the offline
 *   test compiles the SAME code the daemon runs (tests/test-touch-mt.c).
 */
#ifndef NUXEL_MT_H
#define NUXEL_MT_H

#include <linux/input.h>
#include <stdint.h>
#include <string.h>

enum {
  NUXEL_MT_PHASE_NONE = 0,
  NUXEL_MT_PHASE_DOWN = 1,
  NUXEL_MT_PHASE_MOVE = 2,
  NUXEL_MT_PHASE_UP = 3,
  NUXEL_MT_PHASE_CANCEL = 4
};

typedef struct {
  int slot;             /* current ABS_MT_SLOT                      */
  int tracking;         /* current slot-0 tracking id, -1 = lifted  */
  int active;           /* a slot-0 contact is being tracked        */
  int down_pending;     /* tracking id seen, coords not complete    */
  int32_t x, y;         /* last known slot-0 coordinates            */
  int32_t axis_max_x, axis_max_y;
} nuxel_mt_state;

typedef struct {
  int phase;            /* NUXEL_MT_PHASE_*                         */
  int32_t x, y;
  int32_t axis_max_x, axis_max_y;
} nuxel_mt_event;

static inline void nuxel_mt_init(nuxel_mt_state *m,
                                 int32_t axis_max_x, int32_t axis_max_y) {
  memset(m, 0, sizeof *m);
  m->slot = 0;
  m->tracking = -1;
  m->axis_max_x = axis_max_x > 0 ? axis_max_x : 1;
  m->axis_max_y = axis_max_y > 0 ? axis_max_y : 1;
}

/*
 * Feed one raw evdev event.  Returns 1 and fills *out when the event completes
 * a frame that the gesture state machine must see, otherwise 0.
 *
 * Only slot 0 is tracked: the manager owns single-finger screen gestures and
 * pretending to interpret pinch would be dishonest.  Other slots are ignored,
 * but an ABS_MT_SLOT switch back to 0 still works because coordinates and the
 * tracking id are kept per the currently selected slot's last report.
 */
static inline int nuxel_mt_feed(nuxel_mt_state *m,
                                const struct input_event *ev,
                                nuxel_mt_event *out) {
  out->phase = NUXEL_MT_PHASE_NONE;

  if (ev->type == EV_ABS) {
    switch (ev->code) {
      case ABS_MT_SLOT:
        m->slot = ev->value;
        break;
      case ABS_MT_TRACKING_ID:
        if (m->slot != 0) break;
        if (ev->value >= 0) {
          if (!m->active && m->tracking < 0) m->down_pending = 1;
          m->tracking = ev->value;
        } else {
          m->tracking = -1;
        }
        break;
      case ABS_MT_POSITION_X:
        if (m->slot == 0) m->x = ev->value;
        break;
      case ABS_MT_POSITION_Y:
        if (m->slot == 0) m->y = ev->value;
        break;
      default:
        break;
    }
    return 0;
  }

  if (ev->type != EV_SYN) return 0;

  if (ev->code == SYN_DROPPED) {
    /* The kernel dropped events.  Never leave a gesture half-open: report a
     * cancel if a contact was being tracked, then resynchronise. */
    if (m->active) {
      out->phase = NUXEL_MT_PHASE_CANCEL;
      out->x = m->x; out->y = m->y;
      out->axis_max_x = m->axis_max_x; out->axis_max_y = m->axis_max_y;
    }
    m->active = 0;
    m->down_pending = 0;
    m->tracking = -1;
    return out->phase != NUXEL_MT_PHASE_NONE;
  }

  if (ev->code != SYN_REPORT || m->slot != 0) return 0;

  if (m->down_pending) {
    /* Coordinates are complete now; this is the first honest DOWN. */
    m->down_pending = 0;
    m->active = 1;
    out->phase = NUXEL_MT_PHASE_DOWN;
  } else if (m->active && m->tracking >= 0) {
    out->phase = NUXEL_MT_PHASE_MOVE;
  } else if (m->active && m->tracking < 0) {
    m->active = 0;
    out->phase = NUXEL_MT_PHASE_UP;
  } else {
    return 0;
  }

  out->x = m->x;
  out->y = m->y;
  out->axis_max_x = m->axis_max_x;
  out->axis_max_y = m->axis_max_y;
  return 1;
}

### tools/s10plus/a33/nuxel-provision-services.sh
#!/bin/sh
# nuxel-provision-services.sh — provision the Nuxel service users/groups/dirs
# that the hardened systemd units require (briq-10b live deploy, 2026-10-17).
#
# WHY THIS EXISTS
#   The service units nuxel-bridge.service / nuxel-http-bridge.service run as
#   User=nuxel-bridge, nuxel-notifications.service as User=nuxel-notifications,
#   and nuxel-portal.service requires ReadWritePaths=/var/lib/nuxel/permissions.
#   On the live S10+ those identities and paths did not exist, so the units
#   failed at step USER (status=217/USER) and step NAMESPACE (status=226/NAMESPACE).
#   This script is the idempotent, no-flash, userspace-only fix.
#
# SAFETY: userspace only. Never flashes, never touches a partition, never changes
# a kernel or bootloader. Idempotent: safe to run more than once.
set -eu

need_user() {
    if ! id "$1" >/dev/null 2>&1; then
        useradd --system --no-create-home --shell /usr/sbin/nologin "$1"
        echo "created user $1"
    else
        echo "user $1 already present"
    fi
}

need_user nuxel-bridge
need_user nuxel-notifications

mkdir -p /var/lib/nuxel/permissions /var/log/nuxel
chown nuxel:nuxel /var/lib/nuxel/permissions
echo "directories ready: /var/lib/nuxel/permissions (nuxel:nuxel), /var/log/nuxel"

echo "provisioning complete"

### tools/s10plus/a33/nuxel-reboot-mode.sh
#!/bin/bash
# nuxel-reboot-mode.sh — request a one-shot boot mode and reboot, from CLI/live console.
# Usage: nuxel-reboot-mode.sh {verbose|safe|diag|debug|normal}
set -u
MODE="${1:-}"
FLAGS=/var/lib/nuxel/boot
mkdir -p "$FLAGS"
case "$MODE" in
  verbose) echo "requested_by=nuxel-reboot-mode at=$(date -Iseconds)" > "$FLAGS/verbose-once" ;;
  safe)    echo "requested_by=nuxel-reboot-mode at=$(date -Iseconds)" > "$FLAGS/safe-mode-once" ;;
  diag)    echo "requested_by=nuxel-reboot-mode at=$(date -Iseconds)" > "$FLAGS/diag-once" ;;
  debug)   echo "requested_by=nuxel-reboot-mode at=$(date -Iseconds)" > "$FLAGS/debug-once" ;;
  normal)  rm -f "$FLAGS/verbose-once" "$FLAGS/safe-mode-once" "$FLAGS/diag-once" "$FLAGS/debug-once"; echo "all one-shot flags cleared"; exit 0 ;;
  *) echo "usage: nuxel-reboot-mode.sh {verbose|safe|diag|debug|normal}" >&2; exit 2 ;;
esac
echo "one-shot $MODE requested; rebooting now"
systemctl reboot
exit 0
